import time
import json

TTL = 3600

def get_pricing(redis, db, key="pricing_config"):
    cached = redis.get(key)
    if cached is not None:
        return json.loads(cached)

    # miss: try to take a single-flight lock
    locked = redis.set(key + ":lock", "1", nx=True)
    if locked:
        value = db.query_pricing()
        redis.set(key, json.dumps(value), ex=TTL)
        return value

    # someone else holds the lock: spin until the key appears
    while True:
        cached = redis.get(key)
        if cached is not None:
            return json.loads(cached)
        time.sleep(0.01)
